INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Gesetz zur IT-Sicherheit nur für Behörden gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Unternehmen betroffen"}, {"text": "Ja", "correct": false, "because": "KRITIS inklusive"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Behörde überwacht die Einhaltung der IT-Sicherheitsvorschriften?', 3, '[{"text": "BSI", "correct": true, "because": "Bundesamt für Sicherheit in der Informationstechnik"}, {"text": "BKA", "correct": false, "because": "Strafverfolgung"}, {"text": "BMI", "correct": false, "because": "Ministerium"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche regelt ein IT-Sicherheitsgesetz?', 5, '[{"text": "KRITIS-Schutz", "correct": true, "because": "Kritische Infrastrukturen"}, {"text": "Verbraucherschutz", "correct": true, "because": "IT-Sicherheitskennzeichen"}, {"text": "BSI-Befugnisse", "correct": true, "because": "Überwachung"}, {"text": "Webdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IT-SiG 2.0 gilt seit 2021. b) Es betrifft nur KRITIS-Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch UBI betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was übersehst du, wenn du IT-Sicherheit in einem Unternehmen umsetzt?', 4, '[{"text": "KRITIS-Pflichten", "correct": false, "because": "Gesetzlich vorgeschrieben"}, {"text": "Meldepflicht", "correct": false, "because": "Sicherheitsvorfälle melden"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Gesetz nur für große Firmen gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine KRITIS betroffen"}, {"text": "Ja", "correct": false, "because": "Schwellenwerte entscheiden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Sektor wurde mit IT-SiG 2.0 neu als KRITIS definiert?', 3, '[{"text": "Siedlungsabfallentsorgung", "correct": true, "because": "Neu aufgenommen"}, {"text": "Energie", "correct": false, "because": "Bereits in IT-SiG 1.0"}, {"text": "Transport", "correct": false, "because": "Schon früher dabei"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten haben Unternehmen laut IT-SiG?', 5, '[{"text": "Sicherheitsvorfälle melden", "correct": true, "because": "BSI informieren"}, {"text": "Mindeststandards einhalten", "correct": true, "because": "Stand der Technik"}, {"text": "Angriffserkennung", "correct": true, "because": "IT-SiG 2.0 Vorschrift"}, {"text": "Webdesign anpassen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) das BSI Sicherheitslücken detektieren darf und b) IT-SiG nur für öffentliche Netze gilt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch private Netze betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauchst du nicht, um IT-SiG-Vorgaben umzusetzen?', 4, '[{"text": "IDS", "correct": false, "because": "Angriffserkennung nötig"}, {"text": "BSI-Meldung", "correct": false, "because": "Pflicht bei Vorfällen"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss jedes Unternehmen Sicherheitsvorfälle melden?', 2, '[{"text": "Nein", "correct": true, "because": "Nur KRITIS und UBI"}, {"text": "Ja", "correct": false, "because": "Abhängig von Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche neuen Befugnisse bekam das BSI mit IT-SiG 2.0?', 4, '[{"text": "Portscans", "correct": true, "because": "Sicherheitslücken finden"}, {"text": "Bestandsdatenauskunft", "correct": true, "because": "Von TK-Anbietern"}, {"text": "Webdesignprüfung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass IT-SiG nur für KRITIS gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch UBI betroffen"}, {"text": "Ja", "correct": false, "because": "Erweitert mit 2.0"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das IT-SiG?', 3, '[{"text": "IT-Sicherheit erhöhen", "correct": true, "because": "Schutz von Infrastrukturen"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IT-SiG 2.0 führt ein Sicherheitskennzeichen ein. b) Es gilt nur für Energieunternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle KRITIS betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das BSI im IT-SiG?', 4, '[{"text": "Überwachung", "correct": true, "because": "Prüft Sicherheitsmaßnahmen"}, {"text": "Webentwicklung", "correct": false, "because": "Anderer Bereich"}, {"text": "Hardwarekauf", "correct": false, "because": "Nicht Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Unternehmen Bußgelder riskieren?', 2, '[{"text": "Ja", "correct": true, "because": "Bis 20 Mio. Euro"}, {"text": "Nein", "correct": false, "because": "Verstöße strafbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen das IT-SiG effektiv?', 5, '[{"text": "Meldepflicht", "correct": true, "because": "Schnelle Reaktion"}, {"text": "Mindeststandards", "correct": true, "because": "Stand der Technik"}, {"text": "BSI-Kontrolle", "correct": true, "because": "Überwachung"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt IT-SiG 2.0 seit 2020?', 3, '[{"text": "Nein", "correct": true, "because": "Seit Mai 2021"}, {"text": "Ja", "correct": false, "because": "Falsches Jahr"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zum IT-SiG?', 4, '[{"text": "KRITIS meldet Cyberangriff", "correct": true, "because": "Pflicht nach Gesetz"}, {"text": "Webdesign optimieren", "correct": false, "because": "Anderer Zweck"}, {"text": "Daten komprimieren", "correct": false, "because": "Nicht relevant"}]');
